import { test, expect } from '@playwright/test';

test.describe('Mobile Inventory Page Usability', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/sauce-demo');
  });

  test('should display inventory page and burger menu on mobile portrait viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 });
    await expect(page).toHaveURL(/sauce-demo/);

    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeVisible();
    await expect(usernameInput).toHaveValue('standard_user');

    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();
    await expect(passwordInput).toHaveValue('secret_sauce');

    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();

    await loginButton.click();

    const inventoryPage = page.getByRole('region', { name: /inventory/i });
    await expect(inventoryPage).toBeVisible();

    const burgerMenuBtn = page.getByRole('button', { id: '#react-burger-menu-btn' });
    await expect(burgerMenuBtn).toBeVisible();

    const sideMenu = page.locator('.bm-menu');
    await expect(sideMenu).toBeVisible();

    const logoutLink = page.getByRole('link', { id: '#logout_sidebar_link' });
    await expect(logoutLink).toBeVisible();
  });

  test('should open and close burger menu on mobile portrait viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 });
    const burgerMenuBtn = page.getByRole('button', { id: '#react-burger-menu-btn' });
    await expect(burgerMenuBtn).toBeVisible();

    // Open burger menu
    await burgerMenuBtn.click();
    const sideMenu = page.locator('.bm-menu');
    await expect(sideMenu).toBeVisible();

    // Verify logout link is visible
    const logoutLink = page.getByRole('link', { id: '#logout_sidebar_link' });
    await expect(logoutLink).toBeVisible();

    // Close burger menu
    await burgerMenuBtn.click();
    await expect(sideMenu).not.toBeVisible();

    // Verify burger menu button is still visible
    await expect(burgerMenuBtn).toBeVisible();
  });
});
